import RNA
import random

target = "....((((((((....((..(...................)..(((...((....))...((....))........))).......))))))))))...."

random.seed(123456)

def bp_distance(s1, s2):
    p1, p2 = set(), set()
    for ss, ps in [(s1, p1), (s2, p2)]:
        stack = []
        for i, c in enumerate(ss):
            if c == '(':
                stack.append(i)
            elif c == ')':
                j = stack.pop()
                ps.add((j,i))
    return len(p1 ^ p2)

# Parse target pairs
pairs = {}
stack = []
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

best_seq = None
best_dist = 999

# Use soft constraints: penalize non-target base pairs
fc = RNA.fold_compound(target)
# Add soft constraints to favor target structure
# We create a hard constraint: only allow pairs that are in the target
sc = fc.sc_add_f()
for i in range(100):
    for j in range(i+1, 100):
        if (i in pairs and pairs[i] == j) or (j in pairs and pairs[j] == i):
            pass  # target pair: no penalty
        else:
            # penalize non-target pairs
            sc.add(i, j, 0.5)  # small penalty per non-target pair

# Now use the constrained fold compound for inverse folding
for seed in range(50):
    try:
        fc2 = RNA.fold_compound(target)
        sc2 = fc2.sc_add_f()
        for i in range(100):
            for j in range(i+4, 100):
                if (i in pairs and pairs[i] == j) or (j in pairs and pairs[j] == i):
                    pass
                else:
                    sc2.add(i, j, 0.3)

        seq = RNA.inverse_fold(target, None)

        # Check result with unconstrained fold
        fc3 = RNA.fold_compound(seq)
        s, e = fc3.mfe()
        dist = bp_distance(s, target)
        if dist < best_dist:
            best_dist = dist
            best_seq = seq
            print(f"seed {seed}: dist={dist} energy={e:.1f}")
            if dist == 0:
                break
    except Exception as ex:
        pass

print(f"\nBest: dist={best_dist}")
if best_seq:
    print(f"seq={best_seq}")
