import random

target = "....((((((((....((..(...................)..(((...((....))...((....))........))).......))))))))))...."

random.seed(42)
bases = ['A','C','G','U']
complement = {'A':'U', 'U':'A', 'G':'C', 'C':'G', 'A':'U'}

# Parse pair partners
partner = {}
stack = []
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        partner[j] = i
        partner[i] = j

def bp_distance(s1, s2):
    p1, p2 = set(), set()
    for ss, ps in [(s1, p1), (s2, p2)]:
        stack = []
        for i, c in enumerate(ss):
            if c == '(':
                stack.append(i)
            elif c == ')':
                j = stack.pop()
                ps.add((j,i))
    return len(p1 ^ p2)

# Generate good candidate: unpaired=neutral, paired=complementary
def generate_candidate():
    seq = []
    for i in range(100):
        if i in partner and i < partner[i]:
            # Choose a pair type randomly
            pair_type = random.choice(['GC', 'CG', 'AU', 'UA', 'GU', 'UG'])
            seq.append(pair_type[0])
            # We'll fill the partner later
        elif i in partner and i > partner[i]:
            # This is the partner of a previously-chosen position
            j = partner[i]
            seq.append(complement[seq[j]])
        else:
            seq.append(random.choice(bases))
    return ''.join(seq)

